import { defineComponent, markRaw } from 'vue';
import { Container } from 'pixi.js';
import { eventEmitter } from '../../../services/event-emitter';
import { Spine } from '@esotericsoftware/spine-pixi-v8';

export default defineComponent({
    name: 'DetailView',
    props: {
    },
    data() {
        return {
            currentElement: null as Container | null,
            settingName: '',
            elementKey: 0
        };
    },
    computed: {
        sceneOrder(): string {
            if (!this.currentElement) {
                return '';
            }
            let sceneOrder = '';
            let current = this.currentElement as Container;
            let parent = current.parent;
            while (parent && current) {
                const index = parent.getChildIndex(current);
                sceneOrder = index + ',' + sceneOrder;
                current = parent as Container;
                parent = parent.parent;
            }
            return '0,' + sceneOrder;
        },
        tintHex: {
            get(): string {
                if (!this.currentElement || !('tint' in this.currentElement)) {
                    return '#ffffff';
                }
                const element = this.currentElement as Container & { tint: number };
                return '#' + element.tint.toString(16).padStart(6, '0');
            },
            set(hex: string): void {
                if (this.currentElement && 'tint' in this.currentElement) {
                    const element = this.currentElement as Container & { tint: number };
                    element.tint = parseInt(hex.replace('#', ''), 16);
                }
            }
        },
        isSpine(): boolean {
            return this.currentElement!== null && ('skeleton' in this.currentElement);
        },
        spineSkinInfo(): string {
            if (!this.isSpine || !this.currentElement) {
                return '';
            }
            const spine = this.currentElement as Spine;
            const name = spine.skeleton.skin ? spine.skeleton.skin.name : 'unknown';
            let output = `skin: ${name}`;

            spine.state.tracks.forEach((track) => {
                if (!track || !track.animation) {
                    return;
                }
                output += '\n' + track.trackIndex + ':' + track.animation.name;
            });

            return output;
        }
    },
    mounted(): void {
        eventEmitter.on('DEBUG_INSPECTOR_ELEMENT_SELECTED', this.setElement, this);
    },
    methods: {
        setElement(element: Container | null): void {
            this.currentElement = element ? markRaw(element) : null;
            if (element) {
                this.settingName = element.constructor.name + (element.name === null ? '' : '[' + element.name + ']');
            } else {
                this.settingName = '';
            }
            this.elementKey++;
        },
        copySceneOrder(): void {
            const textarea = document.createElement('textarea');
            textarea.value = this.sceneOrder;
            document.body.appendChild(textarea);
            textarea.select();
            document.execCommand('copy');
            document.body.removeChild(textarea);
        }
    }
});
